using System.Globalization;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Sace.Api.Domain;
using Sace.Api.Infrastructure;

namespace Sace.Api.Services;

public record MonetaryConversionRequest(decimal Amount,string Currency,string TargetCurrency,decimal? ExchangeRate,string? ExchangeRateSource);
public record MonetaryConversionResult(bool Success,decimal? ConvertedAmount,decimal? ExchangeRateUsed,string? ExchangeRateSource,string? ErrorCode,string Explanation);
public interface IMonetaryConversionService { MonetaryConversionResult Convert(MonetaryConversionRequest request); }
public sealed class MonetaryConversionService : IMonetaryConversionService {
  private static readonly HashSet<string> SupportedCurrencies=new(StringComparer.OrdinalIgnoreCase){"USD","MXN","EUR"};
  public MonetaryConversionResult Convert(MonetaryConversionRequest request){
    var source=request.Currency?.Trim().ToUpperInvariant();var target=request.TargetCurrency?.Trim().ToUpperInvariant();
    if(string.IsNullOrWhiteSpace(source)||string.IsNullOrWhiteSpace(target))return new(false,null,null,request.ExchangeRateSource,"VALUATION_CURRENCY_REQUIRED","La moneda origen y destino deben estar identificadas.");
    if(!SupportedCurrencies.Contains(source)||!SupportedCurrencies.Contains(target))return new(false,null,null,request.ExchangeRateSource,"VALUATION_CURRENCY_UNSUPPORTED",$"No existe una conversión configurada para {source} → {target}; no se inventó una equivalencia.");
    if(source==target)return new(true,decimal.Round(request.Amount,6,MidpointRounding.AwayFromZero),1m,"SAME_CURRENCY",null,$"{request.Amount} {source}; no se requirió conversión.");
    if(!request.ExchangeRate.HasValue||request.ExchangeRate.Value<=0)return new(false,null,null,request.ExchangeRateSource,"VALUATION_EXCHANGE_RATE_REQUIRED",$"Se requiere un tipo de cambio positivo y trazable para convertir {source} a {target}.");
    if(string.IsNullOrWhiteSpace(request.ExchangeRateSource))return new(false,null,null,null,"VALUATION_EXCHANGE_RATE_SOURCE_REQUIRED","El tipo de cambio no tiene una procedencia identificada.");
    var converted=decimal.Round(request.Amount*request.ExchangeRate.Value,6,MidpointRounding.AwayFromZero);
    return new(true,converted,request.ExchangeRate,request.ExchangeRateSource,null,$"{request.Amount} {source} × {request.ExchangeRate.Value} ({request.ExchangeRateSource}) = {converted} {target}.");
  }
}

public interface ICustomsValuationEngine { Task<CustomsValuationCalculation> CalculateAsync(Guid operationId,Guid? auditId,Guid userId,CancellationToken ct=default); }
public sealed class CustomsValuationEngine(SaceDbContext db,IMonetaryConversionService money,IConfiguration configuration) : ICustomsValuationEngine {
  private sealed record Candidate(OperationDocument Document,DocumentField Field,decimal Amount,string Currency,EvidenceRole Role,int Priority);
  public async Task<CustomsValuationCalculation> CalculateAsync(Guid operationId,Guid? auditId,Guid userId,CancellationToken ct=default){
    var op=await db.TradeOperations.AsNoTracking().Include(x=>x.Documents).ThenInclude(x=>x.DocumentType).Include(x=>x.Documents).ThenInclude(x=>x.Fields).SingleOrDefaultAsync(x=>x.Id==operationId,ct)??throw new KeyNotFoundException("Operación no localizada.");
    var prior=await db.CustomsValuationCalculations.Where(x=>x.TradeOperationId==operationId).MaxAsync(x=>(int?)x.CalculationVersion,ct)??0;
    db.SystemAuditLogs.Add(Log(await ValidUser(userId,ct),"VALUATION_STARTED",operationId,$"Inició valoración técnica v{prior+1}."));await db.SaveChangesAsync(ct);
    var documents=op.Documents.OrderByDescending(x=>x.Version).ThenByDescending(x=>x.UploadedAt).ToList();
    var rate=FindRate(documents,op);var absolute=configuration.GetValue<decimal>("Valuation:AbsoluteTolerance");var percent=configuration.GetValue<decimal>("Valuation:PercentTolerance");
    var baseCandidate=First(documents,["MANIFESTACION_VALOR_MV_MVE"],[DocumentFieldCodes.TransactionValue,DocumentFieldCodes.PricePaid,DocumentFieldCodes.PricePayable])??First(documents,["COMMERCIAL_INVOICE","INVOICE","COVE_ACK"],[DocumentFieldCodes.TotalAmount,DocumentFieldCodes.CommercialValue]);
    var baseAmount=baseCandidate?.Amount??op.CommercialValue;var baseCurrency=baseCandidate?.Currency??op.Currency?.Trim().ToUpperInvariant();
    var declaredCandidate=First(documents,["PEDIMENTO"],[DocumentFieldCodes.DeclaredCustomsValue]);var declared=declaredCandidate?.Amount??op.DeclaredCustomsValueMxn;var targetCurrency=declaredCandidate?.Currency??(op.DeclaredCustomsValueMxn.HasValue?"MXN":baseCurrency);
    var ambiguous=false;var conversionFailure=false;var components=new List<CustomsValuationComponent>();
    if(baseAmount.HasValue&&!string.IsNullOrWhiteSpace(baseCurrency)){var converted=money.Convert(new(baseAmount.Value,baseCurrency!,targetCurrency??baseCurrency!,rate.Rate,rate.Source));conversionFailure|=!converted.Success;var component=new CustomsValuationComponent{ComponentType=ValuationComponentType.TRANSACTION_VALUE,EconomicKey=$"TRANSACTION_VALUE:{baseAmount.Value}:{baseCurrency}",PrimaryDocumentId=baseCandidate?.Document.Id,PrimaryDocumentFieldId=baseCandidate?.Field.Id,RawAmount=baseCandidate?.Field.RawValue??baseAmount.Value.ToString(CultureInfo.InvariantCulture),NormalizedAmount=baseAmount,Currency=baseCurrency,ExchangeRate=converted.ExchangeRateUsed,ExchangeRateSource=converted.ExchangeRateSource,ConvertedAmount=converted.ConvertedAmount,Treatment=ValuationTreatment.INFORMATIONAL,Confidence=baseCandidate?.Field.Confidence,EvidenceDescription=baseCandidate is null?"TradeOperation.CommercialValue (EXISTING_METADATA)":"Valor base documental"};if(baseCandidate is not null)component.Evidence.Add(Evidence(baseCandidate,EvidenceRole.PRIMARY));components.Add(component);}
    AddComponent(ValuationComponentType.FREIGHT,DocumentFieldCodes.FreightAmount,["TRANSPORT_SERVICE_INVOICE","INCREMENTABLE_INVOICE","TRANSPORT_DOCUMENT","MANIFESTACION_VALOR_MV_MVE"],["INCREMENTABLE_PAYMENT"]);
    AddComponent(ValuationComponentType.INSURANCE,DocumentFieldCodes.InsuranceAmount,["INSURANCE_INVOICE","INSURANCE_POLICY","INCREMENTABLE_INVOICE","MANIFESTACION_VALOR_MV_MVE"],["INSURANCE_PAYMENT"]);
    AddComponent(ValuationComponentType.PACKAGING,DocumentFieldCodes.PackagingAmount,["INCREMENTABLE_INVOICE","MANIFESTACION_VALOR_MV_MVE"],[]);
    AddComponent(ValuationComponentType.OTHER_INCREMENTABLE,DocumentFieldCodes.OtherIncrementableAmount,["INCREMENTABLE_INVOICE","MANIFESTACION_VALOR_MV_MVE"],[]);
    var unclassified=FindCandidates(documents,["INCREMENTABLE_INVOICE"],[DocumentFieldCodes.IncrementableTotal,DocumentFieldCodes.TotalAmount],EvidenceRole.PRIMARY,10).Where(x=>!components.Any(c=>c.PrimaryDocumentId==x.Document.Id)).ToList();
    foreach(var candidate in unclassified.GroupBy(x=>x.Document.FileHash??x.Document.Id.ToString()).Select(x=>x.First())){var converted=money.Convert(new(candidate.Amount,candidate.Currency,targetCurrency??candidate.Currency,rate.Rate,rate.Source));conversionFailure|=!converted.Success;var component=new CustomsValuationComponent{ComponentType=ValuationComponentType.UNCLASSIFIED_INCREMENTABLE,EconomicKey=$"UNCLASSIFIED_INCREMENTABLE:{candidate.Document.FileHash??candidate.Document.Id.ToString()}:{candidate.Amount}:{candidate.Currency}",PrimaryDocumentId=candidate.Document.Id,PrimaryDocumentFieldId=candidate.Field.Id,RawAmount=candidate.Field.RawValue,NormalizedAmount=candidate.Amount,Currency=candidate.Currency,ExchangeRate=converted.ExchangeRateUsed,ExchangeRateSource=converted.ExchangeRateSource,ConvertedAmount=converted.ConvertedAmount,Treatment=ValuationTreatment.INFORMATIONAL,Confidence=candidate.Field.Confidence,EvidenceDescription="No fue posible determinar inequívocamente si el gasto es flete, seguro, embalaje u otro incrementable."};component.Evidence.Add(Evidence(candidate,EvidenceRole.PRIMARY));components.Add(component);ambiguous=true;}
    var baseConverted=components.FirstOrDefault(x=>x.ComponentType==ValuationComponentType.TRANSACTION_VALUE)?.ConvertedAmount;
    decimal Total(ValuationComponentType type)=>components.Where(x=>x.ComponentType==type&&x.Treatment==ValuationTreatment.ADD).Sum(x=>x.ConvertedAmount??0);
    var freight=Total(ValuationComponentType.FREIGHT);var insurance=Total(ValuationComponentType.INSURANCE);var packaging=Total(ValuationComponentType.PACKAGING);var other=Total(ValuationComponentType.OTHER_INCREMENTABLE);var increments=freight+insurance+packaging+other;var calculated=baseConverted.HasValue&&!conversionFailure?baseConverted+increments:null;
    decimal? difference=calculated.HasValue&&declared.HasValue?calculated.Value-declared.Value:null;decimal? differencePercent=difference.HasValue&&declared!=0?Math.Abs(difference.Value/declared!.Value*100m):null;
    var outcome=ValuationOutcome.INSUFFICIENT_EVIDENCE;var manual=ambiguous;if(ambiguous)outcome=ValuationOutcome.MANUAL_REVIEW;else if(baseAmount.HasValue&&calculated.HasValue&&declared.HasValue){var match=Math.Abs(difference!.Value)<=absolute||(differencePercent.HasValue&&differencePercent.Value<=percent);outcome=match?ValuationOutcome.MATCH:ValuationOutcome.MISMATCH;}
    var terms=new[]{baseConverted,freight==0?null:freight,insurance==0?null:insurance,packaging==0?null:packaging,other==0?null:other}.Where(x=>x.HasValue).Select(x=>x!.Value.ToString("0.######",CultureInfo.InvariantCulture));var formula=calculated.HasValue?$"{string.Join(" + ",terms)} = {calculated.Value.ToString("0.######",CultureInfo.InvariantCulture)} {targetCurrency}":"No calculable con la evidencia disponible.";
    var explanation=outcome switch{ValuationOutcome.MATCH=>$"El valor técnico coincide dentro de tolerancias explícitas: {absolute} {targetCurrency} o {percent}%.",ValuationOutcome.MISMATCH=>$"Diferencia técnica de {difference} {targetCurrency}; no constituye una conclusión jurídica.",ValuationOutcome.MANUAL_REVIEW=>"Existe un gasto sin categoría inequívoca o evidencia primaria contradictoria; requiere revisión manual.",_=>conversionFailure?"No fue posible convertir todos los importes con un tipo de cambio válido y trazable.":"Falta valor base o valor declarado para completar la comparación."};
    var calculation=new CustomsValuationCalculation{TradeOperationId=operationId,AuditId=auditId,CalculationVersion=prior+1,TransactionValue=baseAmount,Currency=baseCurrency,ExchangeRate=rate.Rate,ExchangeRateSource=rate.Source,TransactionValueConverted=baseConverted,FreightTotal=freight,InsuranceTotal=insurance,PackagingTotal=packaging,OtherIncrementablesTotal=other,IncrementablesTotal=increments,DeclaredCustomsValue=declared,CalculatedCustomsValue=calculated,DifferenceAmount=difference,DifferencePercent=differencePercent,AbsoluteToleranceUsed=absolute,PercentToleranceUsed=percent,Outcome=outcome,Formula=formula,Explanation=explanation,IsManualReviewRequired=manual,Components=components,SnapshotJson=JsonSerializer.Serialize(new{operationId,baseAmount,baseCurrency,targetCurrency,exchangeRate=rate.Rate,exchangeRateSource=rate.Source,absoluteTolerance=absolute,percentTolerance=percent,documents=documents.Select(x=>new{x.Id,x.DocumentType.Code,x.Version,x.FileHash})})};
    db.CustomsValuationCalculations.Add(calculation);db.SystemAuditLogs.Add(Log(await ValidUser(userId,ct),prior==0?"VALUATION_COMPLETED":"VALUATION_RECALCULATED",operationId,$"Valoración v{calculation.CalculationVersion}: {outcome}; cálculo {calculated?.ToString(CultureInfo.InvariantCulture)??"no disponible"} {targetCurrency}."));await db.SaveChangesAsync(ct);return calculation;

    void AddComponent(ValuationComponentType type,string amountCode,string[] primaryTypes,string[] paymentTypes){
      var primary=FindCandidates(documents,primaryTypes,[amountCode],EvidenceRole.PRIMARY,10);var payments=FindCandidates(documents,paymentTypes,[DocumentFieldCodes.PaymentAmount],EvidenceRole.PAYMENT,30);var declaredCode=type switch{ValuationComponentType.FREIGHT=>DocumentFieldCodes.DeclaredFreight,ValuationComponentType.INSURANCE=>DocumentFieldCodes.DeclaredInsurance,ValuationComponentType.PACKAGING=>DocumentFieldCodes.DeclaredPackaging,ValuationComponentType.OTHER_INCREMENTABLE=>DocumentFieldCodes.DeclaredOtherIncrementables,_=>""};var declaredEvidence=FindCandidates(documents,["PEDIMENTO"],[declaredCode],EvidenceRole.DECLARED_VALUE,40);var candidates=primary.Concat(payments).Concat(declaredEvidence).ToList();if(candidates.Count==0)return;var selected=primary.FirstOrDefault()??payments.FirstOrDefault();if(selected is null)return;var distinctPrimary=primary.Where(x=>x.Document.DocumentType.Code is not "TRANSPORT_DOCUMENT" and not "MANIFESTACION_VALOR_MV_MVE").Select(x=>(x.Amount,x.Currency)).Distinct().ToList();if(distinctPrimary.Count>1)ambiguous=true;var converted=money.Convert(new(selected.Amount,selected.Currency,targetCurrency??selected.Currency,rate.Rate,rate.Source));conversionFailure|=!converted.Success;var component=new CustomsValuationComponent{ComponentType=type,EconomicKey=$"{type}:{selected.Amount}:{selected.Currency}",PrimaryDocumentId=selected.Document.Id,PrimaryDocumentFieldId=selected.Field.Id,RawAmount=selected.Field.RawValue,NormalizedAmount=selected.Amount,Currency=selected.Currency,ExchangeRate=converted.ExchangeRateUsed,ExchangeRateSource=converted.ExchangeRateSource,ConvertedAmount=converted.ConvertedAmount,Treatment=ValuationTreatment.ADD,Confidence=selected.Field.Confidence,EvidenceDescription=$"Un componente económico {type} consolidado a partir de {candidates.Select(x=>x.Document.Id).Distinct().Count()} documento(s); las evidencias no multiplican el importe."};foreach(var candidate in candidates.GroupBy(x=>x.Document.FileHash??x.Document.Id.ToString()).Select(x=>x.OrderBy(c=>c.Priority).First())){var evidenceRole=candidate.Document.DocumentType.Code is "TRANSPORT_DOCUMENT" or "MANIFESTACION_VALOR_MV_MVE"?EvidenceRole.SUPPORTING:candidate.Role;component.Evidence.Add(Evidence(candidate,evidenceRole));}components.Add(component);
    }
  }
  private static Candidate? First(List<OperationDocument> docs,string[] types,string[] fields)=>FindCandidates(docs,types,fields,EvidenceRole.PRIMARY,1).FirstOrDefault();
  private static List<Candidate> FindCandidates(List<OperationDocument> docs,string[] types,string[] fields,EvidenceRole role,int priority){var typeOrder=types.Select((x,i)=>(x,i)).ToDictionary(x=>x.x,x=>x.i,StringComparer.OrdinalIgnoreCase);return docs.Where(x=>typeOrder.ContainsKey(x.DocumentType.Code)).SelectMany(d=>d.Fields.Where(f=>fields.Contains(f.FieldCode,StringComparer.OrdinalIgnoreCase)).Select(f=>(d,f))).Select(x=>decimal.TryParse(x.f.NormalizedValue,NumberStyles.Number,CultureInfo.InvariantCulture,out var amount)?new Candidate(x.d,x.f,amount,Currency(x.d,x.f),role,priority+typeOrder[x.d.DocumentType.Code]):null).Where(x=>x is not null).Select(x=>x!).OrderBy(x=>x.Priority).ThenByDescending(x=>x.Document.Version).ToList();}
  private static string Currency(OperationDocument doc,DocumentField field)=>field.Currency??doc.Fields.FirstOrDefault(x=>x.FieldCode==DocumentFieldCodes.Currency)?.NormalizedValue??"";
  private static ValuationComponentEvidence Evidence(Candidate candidate,EvidenceRole role)=>new(){OperationDocumentId=candidate.Document.Id,DocumentFieldId=candidate.Field.Id,EvidenceRole=role,Confidence=candidate.Field.Confidence};
  private static (decimal? Rate,string? Source) FindRate(List<OperationDocument> docs,TradeOperation op){foreach(var code in new[]{"PEDIMENTO","MANIFESTACION_VALOR_MV_MVE"}){var doc=docs.FirstOrDefault(x=>x.DocumentType.Code==code);var field=doc?.Fields.FirstOrDefault(x=>x.FieldCode==DocumentFieldCodes.ExchangeRate);if(decimal.TryParse(field?.NormalizedValue,NumberStyles.Number,CultureInfo.InvariantCulture,out var value)&&value>0)return(value,$"{code}:{doc!.OriginalFileName}");}return op.ExchangeRate is>0?(op.ExchangeRate,"TradeOperation.ExchangeRate"):(null,null);}
  private static SystemAuditLog Log(Guid? user,string action,Guid id,string details)=>new(){UserId=user,Action=action,EntityType="TradeOperation",EntityId=id.ToString(),Details=details};
  private async Task<Guid?> ValidUser(Guid userId,CancellationToken ct)=>userId!=Guid.Empty&&await db.Users.AnyAsync(x=>x.Id==userId,ct)?userId:null;
}

public interface IContributionReconciliationEngine { Task<ContributionCalculation> ReconcileAsync(Guid operationId,Guid? auditId,Guid userId,CancellationToken ct=default); }
public sealed class ContributionReconciliationEngine(SaceDbContext db,IConfiguration configuration) : IContributionReconciliationEngine {
  private static readonly HashSet<string> RecognizedCodes=new(StringComparer.OrdinalIgnoreCase){"IGI","IVA","IEPS","DTA"};
  public async Task<ContributionCalculation> ReconcileAsync(Guid operationId,Guid? auditId,Guid userId,CancellationToken ct=default){
    var op=await db.TradeOperations.AsNoTracking().Include(x=>x.Documents).ThenInclude(x=>x.DocumentType).Include(x=>x.Documents).ThenInclude(x=>x.Fields).SingleOrDefaultAsync(x=>x.Id==operationId,ct)??throw new KeyNotFoundException("Operación no localizada.");var version=(await db.ContributionCalculations.Where(x=>x.TradeOperationId==operationId).MaxAsync(x=>(int?)x.Version,ct)??0)+1;var user=await ValidUser(userId,ct);db.SystemAuditLogs.Add(Log(user,"CONTRIBUTION_RECONCILIATION_STARTED",operationId,$"Inició conciliación de contribuciones v{version}."));await db.SaveChangesAsync(ct);
    var pedimentos=op.Documents.Where(x=>x.DocumentType.Code=="PEDIMENTO").OrderByDescending(x=>x.Version).ToList();var payments=op.Documents.Where(x=>x.DocumentType.Code is "INCREMENTABLE_PAYMENT" or "PURCHASE_PAYMENT" or "INSURANCE_PAYMENT").OrderByDescending(x=>x.Version).ToList();var lines=new List<ContributionLine>();var tolerance=configuration.GetValue<decimal>("Contribution:AbsoluteTolerance");var allowCalculation=configuration.GetValue<bool>("Contribution:EnableTechnicalRateCalculation");
    foreach(var document in pedimentos){var codeFields=document.Fields.Where(x=>x.FieldCode==DocumentFieldCodes.ContributionCode).ToList();foreach(var codeField in codeFields){var group=string.IsNullOrWhiteSpace(codeField.GroupKey)?document.Fields:document.Fields.Where(x=>x.GroupKey==codeField.GroupKey).ToList();var rawCode=codeField.RawValue??codeField.NormalizedValue??"UNKNOWN";var code=codeField.NormalizedValue??rawCode.Trim().ToUpperInvariant();var baseField=group.FirstOrDefault(x=>x.FieldCode==DocumentFieldCodes.ContributionBase);var rateField=group.FirstOrDefault(x=>x.FieldCode==DocumentFieldCodes.ContributionRate);var declaredField=group.FirstOrDefault(x=>x.FieldCode==DocumentFieldCodes.ContributionDeclaredAmount);var calculatedField=group.FirstOrDefault(x=>x.FieldCode==DocumentFieldCodes.ContributionCalculatedAmount);var descriptionField=group.FirstOrDefault(x=>x.FieldCode==DocumentFieldCodes.Description);var taxBase=Decimal(baseField);var rate=Decimal(rateField);var declared=Decimal(declaredField);var calculated=Decimal(calculatedField);if(!calculated.HasValue&&allowCalculation&&RecognizedCodes.Contains(code)&&taxBase.HasValue&&rate.HasValue)calculated=decimal.Round(taxBase.Value*rate.Value/100m,6,MidpointRounding.AwayFromZero);
        var payment=payments.Select(d=>new{Document=d,Code=d.Fields.FirstOrDefault(x=>x.FieldCode==DocumentFieldCodes.ContributionCode),Amount=d.Fields.FirstOrDefault(x=>x.FieldCode is DocumentFieldCodes.ContributionPaidAmount or DocumentFieldCodes.PaymentAmount)}).FirstOrDefault(x=>string.Equals(x.Code?.NormalizedValue,code,StringComparison.OrdinalIgnoreCase));var paid=Decimal(payment?.Amount);var diffCalc=declared.HasValue&&calculated.HasValue?declared-calculated:null;var diffPaid=declared.HasValue&&paid.HasValue?declared-paid:null;var outcome=declared.HasValue&&paid.HasValue?(Math.Abs(diffPaid!.Value)<=tolerance?ContributionOutcome.RECONCILED:ContributionOutcome.MISMATCH):ContributionOutcome.INSUFFICIENT_EVIDENCE;var explanation=outcome switch{ContributionOutcome.RECONCILED=>$"Declarado y pagado coinciden dentro de {tolerance} MXN.",ContributionOutcome.MISMATCH=>$"Diferencia técnica declarado vs pagado: {diffPaid} MXN; no constituye un hallazgo LEGAL.",_=>rate.HasValue?"No existe un pago inequívocamente vinculado por código de contribución.":"No existe pago vinculado y la tasa ausente no se inventó."};lines.Add(new ContributionLine{RawContributionCode=rawCode,RawDescription=descriptionField?.RawValue,RawRate=rateField?.RawValue,RawAmount=declaredField?.RawValue,ContributionCode=code,Description=descriptionField?.RawValue??(RecognizedCodes.Contains(code)?code:"Código no reconocido conservado"),TaxBase=taxBase,Rate=rate,DeclaredAmount=declared,CalculatedAmount=calculated,PaidAmount=paid,DifferenceDeclaredVsCalculated=diffCalc,DifferenceDeclaredVsPaid=diffPaid,Currency=declaredField?.Currency??"MXN",Outcome=outcome,Explanation=explanation,SourceDocumentId=document.Id,SourceFieldId=declaredField?.Id,PaymentDocumentId=payment?.Document.Id});}}
    var status=lines.Count==0?ContributionOutcome.INSUFFICIENT_EVIDENCE:lines.Any(x=>x.Outcome==ContributionOutcome.MISMATCH)?ContributionOutcome.MISMATCH:lines.All(x=>x.Outcome==ContributionOutcome.RECONCILED)?ContributionOutcome.RECONCILED:ContributionOutcome.INSUFFICIENT_EVIDENCE;var calculation=new ContributionCalculation{TradeOperationId=operationId,AuditId=auditId,Version=version,Status=status,Explanation=lines.Count==0?"No se encontraron líneas de contribución estructuradas.":$"Se conciliaron {lines.Count} línea(s) sin convertir diferencias en conclusiones jurídicas.",Lines=lines,SnapshotJson=JsonSerializer.Serialize(new{operationId,tolerance,allowCalculation,documents=op.Documents.Select(x=>new{x.Id,x.DocumentType.Code,x.Version,x.FileHash})})};db.ContributionCalculations.Add(calculation);db.SystemAuditLogs.Add(Log(user,"CONTRIBUTION_RECONCILIATION_COMPLETED",operationId,$"Conciliación v{version}: {status}; {lines.Count} líneas."));await db.SaveChangesAsync(ct);return calculation;
  }
  private static decimal? Decimal(DocumentField? field)=>decimal.TryParse(field?.NormalizedValue,NumberStyles.Number,CultureInfo.InvariantCulture,out var value)?value:null;
  private static SystemAuditLog Log(Guid? user,string action,Guid id,string details)=>new(){UserId=user,Action=action,EntityType="TradeOperation",EntityId=id.ToString(),Details=details};
  private async Task<Guid?> ValidUser(Guid userId,CancellationToken ct)=>userId!=Guid.Empty&&await db.Users.AnyAsync(x=>x.Id==userId,ct)?userId:null;
}
